import React, { useState, useEffect } from 'react';
import { BookOpen, CheckCircle, RotateCw, Award, Plus, Sparkles } from 'lucide-react';
import { fetchDueVocab, reviewVocab, addVocab } from '../services/api';

const LearningDashboard = ({ username, selectedLang, languages }) => {
  const [dueVocab, setDueVocab] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showAnswer, setShowAnswer] = useState(false);
  const [newWord, setNewWord] = useState('');
  const [newTranslation, setNewTranslation] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  useEffect(() => {
    loadDueVocab();
  }, [username, selectedLang]);

  const loadDueVocab = async () => {
    try {
      const res = await fetchDueVocab(username, selectedLang);
      setDueVocab(res.due_items || []);
      setCurrentIndex(0);
      setShowAnswer(false);
    } catch (e) {
      console.error("Failed loading due vocab:", e);
    }
  };

  const handleScoreReview = async (qualityScore) => {
    if (dueVocab.length === 0) return;
    const currentItem = dueVocab[currentIndex];
    try {
      await reviewVocab(currentItem.id, qualityScore);
      if (currentIndex + 1 < dueVocab.length) {
        setCurrentIndex(currentIndex + 1);
        setShowAnswer(false);
      } else {
        loadDueVocab();
      }
    } catch (e) {
      console.error("Error rating SM-2 flashcard:", e);
    }
  };

  const handleAddWord = async () => {
    if (!newWord.trim() || !newTranslation.trim()) return;
    try {
      await addVocab(username, newWord, selectedLang, newTranslation);
      setNewWord('');
      setNewTranslation('');
      setIsAdding(false);
      loadDueVocab();
    } catch (e) {
      console.error("Error adding word:", e);
    }
  };

  const currentItem = dueVocab[currentIndex];
  const langMeta = languages[selectedLang] || { name: selectedLang, flag: '🌐' };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', width: '340px' }}>
      {/* Stats Header */}
      <div className="glass-panel" style={{ padding: '20px' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '14px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Award color="#f59e0b" size={20} />
            <h3 style={{ fontSize: '15px', fontWeight: 600, color: '#fff' }}>SM-2 Learning Stats</h3>
          </div>
          <span style={{ fontSize: '20px' }}>{langMeta.flag}</span>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
          <div style={{ background: 'rgba(255, 255, 255, 0.05)', padding: '10px', borderRadius: '10px', textAlign: 'center' }}>
            <div style={{ fontSize: '18px', fontWeight: 700, color: '#8b5cf6' }}>{dueVocab.length}</div>
            <div style={{ fontSize: '11px', color: '#94a3b8' }}>Cards Due Today</div>
          </div>
          <div style={{ background: 'rgba(255, 255, 255, 0.05)', padding: '10px', borderRadius: '10px', textAlign: 'center' }}>
            <div style={{ fontSize: '18px', fontWeight: 700, color: '#10b981' }}>94%</div>
            <div style={{ fontSize: '11px', color: '#94a3b8' }}>Retention Rate</div>
          </div>
        </div>
      </div>

      {/* Spaced Repetition Flashcard */}
      <div className="glass-panel" style={{ padding: '20px', position: 'relative' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '14px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <BookOpen color="#3b82f6" size={18} />
            <h4 style={{ fontSize: '14px', fontWeight: 600, color: '#fff' }}>Spaced Repetition Review</h4>
          </div>
          <button 
            onClick={() => setIsAdding(!isAdding)}
            style={{ background: 'none', border: 'none', color: '#c084fc', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px', fontSize: '12px' }}
          >
            <Plus size={14} /> Add Word
          </button>
        </div>

        {isAdding && (
          <div style={{ background: 'rgba(255, 255, 255, 0.05)', padding: '12px', borderRadius: '12px', marginBottom: '14px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <input 
              placeholder={`Word in ${langMeta.name}`} 
              value={newWord}
              onChange={(e) => setNewWord(e.target.value)}
              style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', padding: '6px 10px', borderRadius: '6px', fontSize: '12px' }}
            />
            <input 
              placeholder="English Translation" 
              value={newTranslation}
              onChange={(e) => setNewTranslation(e.target.value)}
              style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', padding: '6px 10px', borderRadius: '6px', fontSize: '12px' }}
            />
            <button onClick={handleAddWord} className="glow-btn" style={{ padding: '6px 12px', fontSize: '12px', borderRadius: '6px' }}>
              Save Word
            </button>
          </div>
        )}

        {dueVocab.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '20px 10px', color: '#94a3b8' }}>
            <CheckCircle size={32} color="#10b981" style={{ marginBottom: '8px' }} />
            <p style={{ fontSize: '13px', color: '#fff' }}>All caught up for today!</p>
            <p style={{ fontSize: '11px', marginTop: '4px' }}>Add new vocabulary while chatting to boost your memory curve.</p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <div 
              onClick={() => setShowAnswer(!showAnswer)}
              style={{
                background: 'linear-gradient(135deg, rgba(30, 41, 59, 0.9), rgba(15, 23, 42, 0.9))',
                border: '1px solid rgba(255, 255, 255, 0.15)',
                borderRadius: '14px',
                padding: '24px 16px',
                textAlign: 'center',
                cursor: 'pointer',
                minHeight: '120px',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justify: 'center'
              }}
            >
              <div style={{ fontSize: '20px', fontWeight: 700, color: '#fff', marginBottom: '6px' }}>
                {currentItem.word}
              </div>

              {showAnswer ? (
                <div style={{ fontSize: '14px', color: '#34d399', fontWeight: 500 }}>
                  {currentItem.translation}
                </div>
              ) : (
                <div style={{ fontSize: '11px', color: '#94a3b8', fontStyle: 'italic' }}>
                  Tap card to reveal answer
                </div>
              )}
            </div>

            {showAnswer && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                <div style={{ fontSize: '11px', color: '#94a3b8', textAlign: 'center' }}>Rate your recall quality:</div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '4px' }}>
                  {[1, 2, 3, 4, 5].map((score) => (
                    <button
                      key={score}
                      onClick={() => handleScoreReview(score)}
                      style={{
                        background: score >= 4 ? 'rgba(16, 185, 129, 0.3)' : score >= 3 ? 'rgba(245, 158, 11, 0.3)' : 'rgba(239, 68, 68, 0.3)',
                        border: '1px solid rgba(255, 255, 255, 0.1)',
                        color: '#fff',
                        borderRadius: '6px',
                        padding: '6px 0',
                        fontSize: '12px',
                        fontWeight: 600,
                        cursor: 'pointer'
                      }}
                    >
                      {score}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default LearningDashboard;
